-- FleetPilot MySQL schema (MySQL 8+ / MariaDB 10.5+)
-- Run:  mysql -u root -p < schema.sql
CREATE DATABASE IF NOT EXISTS fleetpilot
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE fleetpilot;

-- IDs are generated by the app (db.nextId), so they are NOT auto-increment.

CREATE TABLE IF NOT EXISTS vehicles (
  id        BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  reg       VARCHAR(30)   NOT NULL DEFAULT '',
  make      VARCHAR(60)   NOT NULL DEFAULT '',
  model     VARCHAR(60)   NOT NULL DEFAULT '',
  year      VARCHAR(10)   NOT NULL DEFAULT '',
  rate      DECIMAL(14,2) NOT NULL DEFAULT 0,
  owner     VARCHAR(120)  NOT NULL DEFAULT '',
  status    VARCHAR(20)   NOT NULL DEFAULT 'Available',  -- Available | Rented | Maintenance | Inactive
  KEY idx_vehicles_reg (reg),
  KEY idx_vehicles_status (status)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS drivers (
  id         BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  name       VARCHAR(120)  NOT NULL DEFAULT '',
  phone      VARCHAR(40)   NOT NULL DEFAULT '',
  license    VARCHAR(60)   NOT NULL DEFAULT '',
  vehicle_id BIGINT UNSIGNED NULL,
  allowance  DECIMAL(14,2) NOT NULL DEFAULT 0,
  status     VARCHAR(20)   NOT NULL DEFAULT '',
  CONSTRAINT fk_drivers_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS clients (
  id     BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  name   VARCHAR(120) NOT NULL DEFAULT '',
  phone  VARCHAR(40)  NOT NULL DEFAULT '',
  idnum  VARCHAR(60)  NOT NULL DEFAULT '',   -- national ID / passport
  dl     VARCHAR(60)  NOT NULL DEFAULT '',   -- driving licence
  KEY idx_clients_name (name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS bookings (
  id           BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  vehicle_id   BIGINT UNSIGNED NULL,
  client_id    BIGINT UNSIGNED NULL,
  booked_on    DATE NULL,
  pickup_date  DATE NULL,
  return_date  DATE NULL,
  deposit      DECIMAL(14,2) NOT NULL DEFAULT 0,
  status       VARCHAR(20) NOT NULL DEFAULT 'Pending',   -- Pending | Confirmed | Cancelled ...
  reminder_ack TINYINT(1)  NOT NULL DEFAULT 0,
  KEY idx_bookings_pickup (pickup_date),
  CONSTRAINT fk_bookings_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL,
  CONSTRAINT fk_bookings_client  FOREIGN KEY (client_id)  REFERENCES clients(id)  ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS rentals (
  id           BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  vehicle_id   BIGINT UNSIGNED NULL,
  client_id    BIGINT UNSIGNED NULL,
  contract     VARCHAR(40) NOT NULL DEFAULT '',
  invoice      VARCHAR(40) NOT NULL DEFAULT '',
  receipt      VARCHAR(40) NOT NULL DEFAULT '',
  pickup_date  DATE NULL,
  pickup_time  TIME NULL,
  return_date  DATE NULL,
  return_time  TIME NULL,
  rate         DECIMAL(14,2) NOT NULL DEFAULT 0,
  days         DECIMAL(8,2)  NOT NULL DEFAULT 0,
  mileage      VARCHAR(30)   NOT NULL DEFAULT '',
  amount       DECIMAL(14,2) NOT NULL DEFAULT 0,
  status       VARCHAR(20)   NOT NULL DEFAULT 'Active',  -- Active | Completed | Cancelled
  fuel         DECIMAL(14,2) NOT NULL DEFAULT 0,
  fuel_charge  DECIMAL(14,2) NOT NULL DEFAULT 0,
  KEY idx_rentals_status (status),
  KEY idx_rentals_pickup (pickup_date),
  KEY idx_rentals_vehicle (vehicle_id),
  CONSTRAINT fk_rentals_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL,
  CONSTRAINT fk_rentals_client  FOREIGN KEY (client_id)  REFERENCES clients(id)  ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS expenses (
  id             BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  vehicle_id     BIGINT UNSIGNED NULL,
  expense_date   DATE NULL,
  category       VARCHAR(40)  NOT NULL DEFAULT '',
  description    VARCHAR(255) NOT NULL DEFAULT '',
  qty            DECIMAL(10,2) NOT NULL DEFAULT 1,
  amount         DECIMAL(14,2) NOT NULL DEFAULT 0,
  billable       TINYINT(1)   NOT NULL DEFAULT 0,
  bill_client_id BIGINT UNSIGNED NULL,
  charge_amount  DECIMAL(14,2) NOT NULL DEFAULT 0,
  source         VARCHAR(10)  NOT NULL DEFAULT 'manual',  -- manual | rental
  rental_id      BIGINT UNSIGNED NULL,
  KEY idx_expenses_date (expense_date),
  KEY idx_expenses_category (category),
  CONSTRAINT fk_expenses_vehicle FOREIGN KEY (vehicle_id)     REFERENCES vehicles(id) ON DELETE SET NULL,
  CONSTRAINT fk_expenses_client  FOREIGN KEY (bill_client_id) REFERENCES clients(id)  ON DELETE SET NULL,
  CONSTRAINT fk_expenses_rental  FOREIGN KEY (rental_id)      REFERENCES rentals(id)  ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS payments (
  id           BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  rental_id    BIGINT UNSIGNED NULL,
  payment_date DATE NULL,
  amount       DECIMAL(14,2) NOT NULL DEFAULT 0,
  method       VARCHAR(30)  NOT NULL DEFAULT '',
  note         VARCHAR(255) NOT NULL DEFAULT '',
  KEY idx_payments_date (payment_date),
  CONSTRAINT fk_payments_rental FOREIGN KEY (rental_id) REFERENCES rentals(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS driver_allowances (
  id         BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  driver_id  BIGINT UNSIGNED NULL,
  week_start DATE NULL,
  amount     DECIMAL(14,2) NOT NULL DEFAULT 0,
  note       VARCHAR(255) NOT NULL DEFAULT '',
  CONSTRAINT fk_allow_driver FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Single-row table: settings, id counter, period and sync metadata.
CREATE TABLE IF NOT EXISTS app_state (
  id             TINYINT UNSIGNED NOT NULL PRIMARY KEY DEFAULT 1,
  settings       JSON NULL,
  next_id        BIGINT UNSIGNED NOT NULL DEFAULT 1,
  period         JSON NULL,
  last_modified  VARCHAR(40) NULL,
  file_name      VARCHAR(255) NULL,
  workbook_dirty TINYINT(1) NOT NULL DEFAULT 1,
  revision       INT UNSIGNED NOT NULL DEFAULT 0,
  saved_at       DATETIME NULL,
  CONSTRAINT chk_app_state_single CHECK (id = 1)
) ENGINE=InnoDB;

INSERT IGNORE INTO app_state (id, next_id, revision) VALUES (1, 1, 0);

